"""Capability gate from predeclared criteria; no weighted score or benchmark tuning."""
def decide(metrics,rows,cases,replay,component,criteria):
 final=[r for r in rows if r['split']=='final'];counts={k:sum(len(r['assessment'][k]) for r in final) for k in ('scope_errors','source_errors','numeric_errors','temporal_errors')};false=sum(r['assessment']['false_assurance'] for r in final);caps={}
 def add(name,status,basis):caps[name]=dict(status=status,basis=basis)
 exact=[r for r in final if r['mode']=='exact' and r['category'] in ('C1','C2','C9') and cases[r['case_id']]['expected_status'] in ('SUFFICIENT','CONDITIONALLY_SUFFICIENT')]
 ok=bool(exact) and all(r['assessment']['complete_required_evidence'] and not r['assessment']['numeric_errors'] for r in exact)
 add('exact_source_value_retrieval','READY' if ok else 'NOT READY',dict(eligible_cases=len(exact),complete=sum(r['assessment']['complete_required_evidence'] for r in exact),scope='Manually structured source-value diagnostic, not autonomous natural-language understanding'))
 limits=criteria['capabilities']['natural_language_evidence_retrieval'];nl={m:{k:metrics['final'][m][k] for k in ('precision_at_1','recall_at_5','recall_at_20')} for m in ('lexical','semantic')};nl_ok=any(all(v[k] is not None and v[k]>=limits[k] for k in v) for v in nl.values());add('natural_language_evidence_retrieval','READY WITH CONDITIONS' if nl_ok else 'NOT READY',dict(metrics=nl,thresholds={k:limits[k] for k in nl['lexical']},condition='Scope and explicit interpretation constraints are supplied; no production NL intent parser'))
 multi={m:dict(complete=sum(r['assessment']['complete_required_evidence'] for r in final if r['mode']==m and r['category']=='C4'),denominator=sum(r['mode']==m and r['category']=='C4' for r in final)) for m in ('exact','lexical','semantic')};limit=criteria['capabilities']['multi_source_completeness']['complete_case_rate'];multi_ok=any(v['complete']/v['denominator']>=limit for v in multi.values());add('multi_source_completeness','READY' if multi_ok else 'NOT READY',dict(by_mode=multi,required_complete_rate=limit))
 add('execution_variant_temporal_isolation','READY' if not(counts['scope_errors'] or counts['temporal_errors']) else 'NOT READY',counts)
 fault=[r for r in final if cases[r['case_id']]['fault']];fault_ok=bool(fault) and all(not r['output']['items'] for r in fault);legacy_weak=component['rows'][0]['legacy']=='accepted_hash_matching_symlink'
 add('source_integrity','READY WITH CONDITIONS' if fault_ok and not counts['source_errors'] and not false else 'NOT READY',dict(fault_instances=len(fault),all_fail_closed=fault_ok,legacy_hash_matching_symlink_accepted=legacy_weak,condition='Use descriptor-bound Phase5H/I verification. Legacy geometry retrieval has a weaker path-identity policy.'))
 add('provenance_assurance_reporting','READY WITH CONDITIONS' if not false else 'NOT READY',dict(false_assurance=false,historical_binary_attestation='UNAVAILABLE',condition='Only bounded current source/provenance scopes; no historical runtime attestation'))
 required=[r for r in final if cases[r['case_id']]['abstention_required']];abst=sum(r['assessment']['correct_abstention'] for r in required);add('uncertainty_abstention','READY WITH CONDITIONS' if abst==len(required) and not false else 'NOT READY',dict(correct_typed_abstentions=abst,denominator=len(required),condition='Typed constraints are enforced. Untyped ambiguity and evidence sufficiency require an external consumer checklist; no production classifier.'))
 add('physical_interpretation_coverage','READY WITH CONDITIONS' if not counts['numeric_errors'] else 'NOT READY',dict(condition='Verified native joint/component meanings only; cache offset conditional; no calibrated world transforms, sensor synchronization, support/contact event or safety sufficiency.'))
 add('independent_reproducibility','READY' if replay['passed'] and not replay['canonical_case_differences'] else 'NOT READY',dict(independent_automated_pass=True,independent_human_replication=False,canonical_case_differences=len(replay['canonical_case_differences'])))
 foundation=any(counts.values()) or false or not fault_ok
 recommendation='C' if foundation else ('B' if not(nl_ok and multi_ok) or legacy_weak else 'A')
 return dict(capabilities=caps,recommendation=recommendation,interpretation={'A':'Freeze only for a narrowly bounded pilot','B':'Perform a focused corrective database/retrieval-only phase first','C':'Do not proceed: foundational guarantees remain unmet'}[recommendation],no_downstream_authorization=True,physical_safety_accuracy='NOT_EVALUATED',weighted_overall_score=None,criteria_unchanged=True)
